import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第二十四章","description":"《正易心法》第二十四章——画卦取象，本为特物：羲皇非出私意，特以顺时应物，见于日用；以钱博与优人呈伎二例说明行止坐卧皆是《易》，而百姓日用而罔觉。","frontmatter":{"title":"正易心法·第二十四章","description":"《正易心法》第二十四章——画卦取象，本为特物：羲皇非出私意，特以顺时应物，见于日用；以钱博与优人呈伎二例说明行止坐卧皆是《易》，而百姓日用而罔觉。","category":"guide","aliases":["正易心法第二十四章","画卦取象本为特物","见于日用"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-24.md","filePath":"yijing/zheng-yi-xin-fa/chapter-24.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-24.md"},x=p({...c,setup(u){const i=[{id:"z24-01",label:"一、本为特物",showLabel:!0,sentences:[["画卦取象，本为",{text:"特物",glossary:"tewu"},"。见于",{text:"曰用",glossary:"riyong"},"，无所不合。"]],note:["伏羲画卦取象，本来是为了特定的事物；它体现在日常生活之中，没有不符合的地方。（**本章是《正易心法》的「落地章」**：前二十三章讲象、数、本体、变复、文献批评，本章把它们全部落到最日常的地方——**《易》不在书本，在日用之间。**「曰用」的「曰」通「日」，即日用。）"]},{id:"z24-02",label:"二、顺时应物",showLabel:!0,sentences:[["羲皇画卦，非谓出私意。撰写一《易》道于",{text:"方册",glossary:"fangce"},"上，以诲人也。特以顺时应物，则以见于曰用之间耳。"]],note:["伏羲画卦，不是说他出于个人的私意，把一部《易》道写在书册上来教导人；只是顺应时机、应对万物，便体现在日常生活之间罢了。（**这是「发现」与「创造」之别**：伏羲不是「创作」卦画，而是「发现」了本来就存在于万物中的道理，用卦画的形式呈现出来。这与第二十章「本之自然」、第二十六章「气序自然」是同一个立场。）"]},{id:"z24-03",label:"三、钱博之喻",showLabel:!0,sentences:[["以",{text:"粗迹",glossary:"cuji"},"言之，如以",{text:"钱博",glossary:"qianbo"},"，六纯字，乾也。六纯背，坤也。",{text:"差互",glossary:"chahu"},"，六子也。若反则未胜，至纯则乾坤成矣。"]],note:["用粗浅的例子来说：比如用铜钱游戏——六枚全部字面朝上，是乾；六枚全部背面朝上，是坤；字背混杂参差，是六子；还有翻转未定则「未胜」，达到纯粹则乾坤成。（**日常游戏里，就演着第二十、二十一章的真体与假合**：「至纯」＝乾坤真体（有定实），「差互」＝六子假合（无定实）。）"]},{id:"z24-04",label:"四、优人之喻",showLabel:!0,sentences:[["又如",{text:"优人呈伎",glossary:"yourenChengji"},"，壮者任其难，六子也。老者",{text:"敛其利",glossary:"lianqili"},"，乾坤也。此皆理之自然。"]],note:["又比如艺人表演技艺：壮年人承担高难度的表演，是六子；老年人收取利益，是乾坤。这些都是自然之理。（**老者看似不动，但所有壮者的表演最终都是为老者服务的**——这正是第十章「圣人尽乾、贤人尽坤」与第十一章「破体炼之，纯体乃成」在日常生活中的影子。）"]},{id:"z24-05",label:"五、举天下皆易",showLabel:!0,sentences:[["即此理以察其余，则是行止坐卧",{text:"纤悉",glossary:"xianxi"},"举天下皆《易》，",{text:"无可拣择",glossary:"wukeJianze"},"者。"]],note:["用这个道理来观察其余的一切，那么行走、停止、坐下、躺卧，细微详尽，整个天下都是《易》，没有可以挑选排除的。（**「无可拣择」四个字很重**：不是「有些事是《易》，有些不是」，而是**没有一件事在《易》之外**——无从取舍，因为你取舍的每一个动作本身就在《易》中。）"]},{id:"z24-06",label:"六、百姓罔觉",showLabel:!0,sentences:[["但百姓",{text:"昏昏",glossary:"hunhun"},"，曰用之而",{text:"罔觉",glossary:"wangjue"},"矣。"]],note:["只是普通百姓懵懵懂懂，日日使用却不自知罢了。（《系辞传》说「百姓日用而不知」；麻衣改一字作「**罔觉**」——**「不知」是缺乏知识，「罔觉」是不自觉。** 百姓从未学过《易》，但他们的行止坐卧都在用《易》；**真正的问题不是「不知」，而是「昏昏」：处于混沌状态，感觉不到自己在用《易》。** 所以学《易》的目的，不是获得新知识，而是**从「昏昏」变成「觉」**。）"]}],o=[{id:"tewu",term:"特物",pinyin:"tè wù",meaning:"特定的事物。每个卦象对应特定的物象，非空言。"},{id:"riyong",term:"曰用",pinyin:"rì yòng",meaning:"日用，「曰」通「日」。体现在日常生活之中。"},{id:"fangce",term:"方册",pinyin:"fāng cè",meaning:"书册。古代书写用的方形木牍或书册。"},{id:"cuji",term:"粗迹",pinyin:"cū jì",meaning:"浅显的例子。粗迹是粗浅的痕迹，言下之意还有细迹。"},{id:"qianbo",term:"钱博",pinyin:"qián bó",meaning:"古代用铜钱游戏或占卜的方式。"},{id:"chahu",term:"差互",pinyin:"cī hù",meaning:"字背混杂，参差不一。即阴阳混杂，对应六子。"},{id:"yourenChengji",term:"优人呈伎",pinyin:"yōu rén chéng jì",meaning:"艺人表演技艺。优人是古代艺人、演员。"},{id:"lianqili",term:"敛其利",pinyin:"liǎn qí lì",meaning:"收取利益。老者不直接表演，却收取报酬——对应乾坤真体。"},{id:"xianxi",term:"纤悉",pinyin:"xiān xī",meaning:"细微详尽。纤是细小，悉是全部。"},{id:"wukeJianze",term:"无可拣择",pinyin:"wú kě jiǎn zé",meaning:"没有可以挑选排除的。《易》无处不在。"},{id:"hunhun",term:"昏昏",pinyin:"hūn hūn",meaning:"懵懵懂懂、不清醒、不自知的状态。"},{id:"wangjue",term:"罔觉",pinyin:"wǎng jué",meaning:"不自觉。罔是不，觉是察觉。麻衣改《系辞》「日用而不知」为「罔觉」。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第二十四章" tabindex="-1">正易心法·第二十四章 <a class="header-anchor" href="#正易心法·第二十四章" aria-label="Permalink to &quot;正易心法·第二十四章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是《正易心法》的**「落地章」**，把前二十三章的义理落实到最日常的生活中：</p><p><strong>核心命题</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《易》不在书本，在日用之间</span></span>
<span class="line"><span>  画卦取象，本为特物（每卦对应具体事物）</span></span>
<span class="line"><span>  见于日用，无所不合（日用中处处是《易》）</span></span></code></pre></div><p><strong>两个例子（粗迹）</strong>：</p><table tabindex="0"><thead><tr><th>例</th><th>内容</th></tr></thead><tbody><tr><td><strong>钱博</strong></td><td>六纯字＝乾，六纯背＝坤，差互＝六子；至纯则乾坤成</td></tr><tr><td><strong>优人呈伎</strong></td><td>壮者任难＝六子，老者敛利＝乾坤</td></tr></tbody></table><p><strong>结论</strong>：<strong>行止坐卧，纤悉天下，皆《易》；百姓日用而罔觉。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「顺时应物」</strong>——这是本章最要紧的一句：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统观点：伏羲仰观天文、俯察地理，「画」出八卦，写成《易》书来教导后人</span></span>
<span class="line"><span>          = 圣人创作（由上而下）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣的纠正：伏羲画卦不是「创作」，而是「发现」</span></span>
<span class="line"><span>           顺应时机、应对万物，把本来就存在于万物中的道理用卦画呈现</span></span>
<span class="line"><span>           = 发现自然（由下而上）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>关键区别：</span></span>
<span class="line"><span>  创作（私意）：伏羲 → 发明卦画 → 对应万物（卦画是人为的）</span></span>
<span class="line"><span>  发现（顺时应物）：万物 → 本有《易》理 → 伏羲发现 → 卦画（卦画是万物本有之理的呈现）</span></span></code></pre></div><p><strong>《易》理在日用中的三层结构</strong>：</p><table tabindex="0"><thead><tr><th>层</th><th>内容</th></tr></thead><tbody><tr><td>第一层（书本）</td><td>六十四卦的卦画、卦辞、爻辞——文字符号，指向义理</td></tr><tr><td>第二层（义理）</td><td>阴阳消长、真体假合、反对变复——前二十三章建立的体系</td></tr><tr><td>第三层（日用）</td><td>行止坐卧，纤悉天下——义理在万物中的自然体现</td></tr></tbody></table><p><strong>麻衣的主张：第三层（日用）才是《易》的本来面目；第二层是理解第三层的工具；第一层只是第三层的记录。</strong></p><p><strong>「罔觉」与「不知」的一字之差</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《系辞传》：百姓日用而不知（不知＝缺乏知识）</span></span>
<span class="line"><span>麻衣：百姓日用而罔觉（罔觉＝不自觉）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣的深意：《易》不是需要「学」才能「用」的</span></span>
<span class="line"><span>            百姓从未学过，但他们的行止坐卧都在用《易》</span></span>
<span class="line"><span>            真正的问题不是「不知」，而是「昏昏」</span></span></code></pre></div><p><strong>学《易》的真正目的</strong>：不是获得新知识，而是<strong>从「昏昏」变成「觉」</strong>——觉察到自己本来就在用的《易》理。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读「顺时应物」——<strong>「发现」与「创作」之别，是全章的枢纽</strong>；</li><li>再看两个「粗迹」（钱博、优人）——<strong>粗迹是入口，不是全部</strong>；</li><li>最后读「罔觉」——<strong>这一字之改，是全章的分量。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>本为特物</strong>：每卦对应特定事物。</li><li><strong>顺时应物</strong>：伏羲是发现者，不是创造者。</li><li><strong>钱博</strong>：六纯字乾、六纯背坤、差互六子。</li><li><strong>优人</strong>：壮者任难为六子，老者敛利为乾坤。</li><li><strong>举天下皆易</strong>：行止坐卧，无可拣择。</li><li><strong>百姓罔觉</strong>：日用而不自觉。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,22)),e(r,{colophon:"本为特物 · 顺时应物 · 行止坐卧皆易 · 百姓罔觉",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十四章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「见于曰用」「曰用之而罔觉」之「曰」皆通「日」（日用），此处依底本录入、以上文说明，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"顺时应物",pinyin:["shùn","shí"],meaning:"伏羲画卦不是创作而是发现：顺应时机、应对万物，把本有的道理用卦画呈现出来。"},{term:"钱博",pinyin:["qián","bó"],meaning:"用铜钱游戏。六纯字＝乾，六纯背＝坤，差互＝六子——日常游戏中就演着真体与假合。"},{term:"优人呈伎",pinyin:["yōu","rén"],meaning:"艺人表演。壮者任难＝六子，老者敛利＝乾坤——老者不动，却是一切的根基。"},{term:"无可拣择",pinyin:["wú","kě"],meaning:"没有可以挑选排除的。《易》无处不在——不是「有些事是《易》」，而是没有一件事在《易》之外。"},{term:"百姓罔觉",pinyin:["wǎng","jué"],meaning:"麻衣改《系辞》「日用而不知」为「日用而罔觉」——「不知」是缺乏知识，「罔觉」是不自觉。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是**「落地章」**，把前二十三章的义理落实到日常生活中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>核心命题：《易》不在书本，在日用之间</span></span>
<span class="line"><span>两个例子：钱博（六纯字乾、六纯背坤、差互六子）</span></span>
<span class="line"><span>         优人呈伎（壮者任难＝六子，老者敛利＝乾坤）</span></span>
<span class="line"><span>结论：行止坐卧，纤悉举天下皆《易》，百姓日用而罔觉</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「顺时应物」——发现与创造之别</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创作（私意）：伏羲 → 发明卦画 → 对应万物（卦画是人为的）</span></span>
<span class="line"><span>发现（顺时应物）：万物 → 本有《易》理 → 伏羲发现 → 卦画</span></span></code></pre></div><p><strong>这是本章的枢纽</strong>——与第二十章「本之自然」、第二十六章「气序自然」同一立场。</p><p><strong>「《易》在日用」的三层结构</strong>：</p><table tabindex="0"><thead><tr><th>层</th><th>内容</th></tr></thead><tbody><tr><td>书本</td><td>卦画、卦辞、爻辞（记录）</td></tr><tr><td>义理</td><td>阴阳消长、真体假合、变复（工具）</td></tr><tr><td><strong>日用</strong></td><td><strong>行止坐卧皆《易》（本来面目）</strong></td></tr></tbody></table><p><strong>「罔觉」与「不知」的一字之差</strong>：麻衣改《系辞》「日用而不知」为「日用而罔觉」——这看似很小的改动，其实很关键：<strong>「不知」是缺乏知识；「罔觉」是不自觉。</strong> 百姓从未学过《易》，但他们的行止坐卧都在用《易》；<strong>真正的问题不是「不知」，而是「昏昏」。</strong></p><p><strong>与第二十三章的关系（破与立）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第二十三章（破）：古今传易，舛讹为多 → 书本层面有错误</span></span>
<span class="line"><span>第二十四章（立）：画卦取象，见于日用 → 超越书本，回归日用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>合读：书本有错误，不要紧——因为《易》本来就不在书本里</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>记住这一句的反问：<strong>我判断一个人懂不懂《易》，是看他能背多少卦辞，还是看他活着的样子？</strong></li><li>把「钱博」「优人」两个例子当作<strong>入口</strong>：它们不是全部，是「粗迹」；</li><li>最后问自己：<strong>今天有没有一个瞬间，我「觉」到自己在用《易》？</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>伏羲画卦取象，本来是为了特定的事物；它体现在日常生活之中，没有不符合的地方。</p><p>伏羲画卦，不是说他出于个人的私意，把一部《易》道写在书册上来教导人；只是顺应时机、应对万物，便体现在日常生活之间罢了。</p><p>用粗浅的例子来说：比如用铜钱游戏——六枚全部字面朝上，是乾；六枚全部背面朝上，是坤；字背混杂参差，是六子；还有翻转未定则「未胜」，达到纯粹则乾坤成。</p><p>又比如艺人表演技艺：壮年人承担高难度的表演，是六子；老年人收取利益，是乾坤。这些都是自然之理。</p><p>用这个道理来观察其余的一切，那么行走、停止、坐下、躺卧，细微详尽，整个天下都是《易》，没有可以挑选排除的。</p><p>只是普通百姓懵懵懂懂，日日使用却不自知罢了。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第二十四章是全书最轻也最重的一章——<strong>它把前面二十三章的千斤义理，放进了两个小孩都能看懂的场景里：抛铜钱、看戏。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「顺时应物」</strong>——这四个字把伏羲从「发明家」变成了「发现者」。<strong>卦画不是他造出来的，是他看见的。</strong></li><li><strong>「钱博」的比喻</strong>——我很喜欢这个例子：<strong>六枚铜钱全字是乾，全背是坤，混杂是六子。</strong> 麻衣用抛铜钱这种最随意的动作，说第二十、二十一章最重的话（真体与假合）。<strong>「至纯则乾坤成矣」——原来抛铜钱也有它的「至纯」。</strong></li><li><strong>「优人呈伎」</strong>——壮者在台上翻跟斗，老者在后台收钱。<strong>麻衣说：这不就是六子和乾坤吗？</strong> 我读到这句时愣了一下：<strong>我以为的「主角」，是台前的壮者；但在结构上，真正不动、真正在根上的，是台后的老者。</strong></li><li><strong>「无可拣择」</strong>——没有一件事在《易》之外。<strong>这不是「《易》也能解释这些」，是「这些本来就在《易》中」。</strong></li><li><strong>「罔觉」与「不知」</strong>——一字之差，是本章最锋利的地方。<strong>「不知」是知识的问题，「罔觉」是醒不醒的问题。</strong> 麻衣把问题从「你懂不懂」改成了「你醒不醒」。</li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>读完这四十二章之后，我和从未读过《易》的普通百姓，究竟有什么不同？</strong> 我的看法是：<strong>差别不在「知道多少」，而在「是否看见」。</strong> 百姓日用《易》而不自觉，我日用《易》而自觉——<strong>但「自觉」是否真的比「不自觉」更好？</strong> 庄子的回答可能是「知鱼之乐者非鱼也」；<strong>而麻衣的回答大概是：觉与不觉都是《易》在运行，但「觉」是这本书的「人」——它等的就是那个被它改变的人。</strong> 所以「觉」不是优越，是<strong>接力</strong>：<strong>你觉了，才有资格把这本书交给下一个「其人」。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「落处」（本章的答案是：落处在日用）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-20">第二十章 · 唯乾与坤</a> — 真体（钱博之喻中的「至纯」）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-21">第二十一章 · 乾坤杂气</a> — 假合（钱博之喻中的「差互」）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-23">第二十三章 · 舛讹为多</a> — 破书本之误（本章是立日用之本）</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「百姓日用而不知」：麻衣改一字作「罔觉」</li></ul>`,28))])}}});export{m as __pageData,x as default};
